    readyName = ".paic_ready_v061.json"
    WS_OVERLAPPED=0x00000000; WS_CAPTION=0x00C00000; WS_SYSMENU=0x00080000; WS_MINIMIZEBOX=0x00020000; WS_VISIBLE=0x10000000; WS_CHILD=0x40000000
    SS_LEFT=0; PBS_SMOOTH=0x01; SW_SHOW=5; WM_DESTROY=0x0002; WM_CLOSE=0x0010; WM_SETFONT=0x0030; WM_APP=0x8000; WM_APP_STATUS=WM_APP+1; WM_APP_DONE=WM_APP+2
    PBM_SETRANGE32=0x0400+6; PBM_SETPOS=0x0400+2; COLOR_WINDOW=5; IDC_ARROW=32512
    MB_OK=0x00000000; MB_ICONERROR=0x00000010; MB_ICONWARNING=0x00000030; MB_ICONINFORMATION=0x00000040
